package spireledger;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
/** Read-only summaries, explicit denominators, separate result and observation populations. */
final class StatsIndex {
 static final class Metric {
  final String key,unit;double numerator,denominator,value;int eligible_count,excluded_count;String unavailable_reason="";
  Metric(String key,String unit){this.key=key;this.unit=unit;}
  void add(double n,double d){numerator+=n;denominator+=d;eligible_count+=unit.equals("count")?(d>0?(int)d:1):(int)d;value=denominator==0?0:numerator/denominator;}
 }
 static final class Run {
  String id,playId="",character="unknown",outcome="incomplete",session="",source,actor="unknown",seed="",lastBranch="";long time;int ascension=-1,floor,deckSize=-1,pathExcluded;boolean fixture,current,conflict;Boolean heart;Double playtime;
  final Set<String> deck=new LinkedHashSet<>();final Set<Integer> acts=new HashSet<>();final Map<String,double[]> values=new LinkedHashMap<>();final Set<String> available=new HashSet<>();
  void add(String key,double n,double d){double[] a=values.computeIfAbsent(key,k->new double[2]);a[0]+=n;a[1]+=d;}
 }
 static final class Index {final List<Run> nativeRuns=new ArrayList<>(),notesRuns=new ArrayList<>();final List<String> errors=new ArrayList<>();int nativeDuplicates,unlinked,conflicts;}
 static final class Filter {String character="",scope="native",source="all";int ascension=-1,days,minSamples=1;long from,to;boolean heart=true,includeAbandon=false,slOnly=false;}
 static String str(JsonObject o,String k){return HistoryIndex.str(o,k);}static JsonObject obj(JsonObject o,String k){return HistoryIndex.obj(o,k);}static JsonArray arr(JsonObject o,String k){return HistoryIndex.array(o,k);}static int num(JsonObject o,String k,int d){return HistoryIndex.num(o,k,d);}
 static boolean arrayField(JsonObject o,String k){return o.has(k)&&o.get(k).isJsonArray();}
 static Boolean bool(JsonObject o,String key){JsonElement v=o.get(key);return v!=null&&v.isJsonPrimitive()&&v.getAsJsonPrimitive().isBoolean()?v.getAsBoolean():null;}
 static Double number(JsonObject o,String key){try{JsonElement v=o.get(key);if(v!=null&&v.isJsonPrimitive()&&v.getAsJsonPrimitive().isNumber()){double n=v.getAsDouble();return Double.isFinite(n)?n:null;}}catch(Exception ignored){}return null;}
 static String cardId(String id){return id.replaceFirst("\\+\\d*$","");}
 static void deck(Run r,JsonArray cards,boolean objects){r.deckSize=cards.size();r.deck.clear();for(JsonElement e:cards){String id=objects&&e.isJsonObject()?str(e.getAsJsonObject(),"id"):e.isJsonPrimitive()?e.getAsString():"";if(!id.isEmpty())r.deck.add(cardId(id));}}
 static Run nativeRun(JsonObject o,String fallback){Run r=new Run();r.source="native";r.playId=str(o,"play_id");r.id=r.playId.isEmpty()?"native-file:"+fallback:r.playId;r.seed=str(o,"seed_played");r.character=str(o,"character_chosen");r.ascension=num(o,"ascension_level",-1);r.floor=num(o,"floor_reached",0);Double stamp=number(o,"timestamp");r.time=stamp==null?0:(long)(stamp*1000);r.playtime=number(o,"playtime");r.session=str(o,"session_kind");r.fixture="test_fixture".equals(str(o,"dataset_origin"));
  Boolean victory=bool(o,"victory");String killed=str(o,"killed_by");boolean abandoned=Boolean.TRUE.equals(bool(o,"abandoned"))||Boolean.TRUE.equals(bool(o,"is_abandoned"))||killed.equalsIgnoreCase("Abandoned");boolean hpZero=false;JsonArray hp=arr(o,"current_hp_per_floor");if(hp.size()>0)try{hpZero=hp.get(hp.size()-1).getAsInt()<=0;}catch(Exception ignored){}
  r.outcome=abandoned?"abandon":Boolean.TRUE.equals(victory)?"victory":Boolean.FALSE.equals(victory)&&(!killed.isEmpty()||hpZero)?"death":"incomplete";
  if(r.outcome.equals("death"))r.heart=false;else if(r.outcome.equals("victory")){if(o.has("heart_kill"))r.heart=bool(o,"heart_kill");else if(arrayField(o,"damage_taken")){boolean heart=false;for(JsonElement e:arr(o,"damage_taken"))if(e.isJsonObject()&&"The Heart".equals(str(e.getAsJsonObject(),"enemies")))heart=true;r.heart=heart;}}
  if(o.has("master_deck")&&o.get("master_deck").isJsonArray())deck(r,arr(o,"master_deck"),false);
  int act=1;for(JsonElement e:arr(o,"path_per_floor")){if(e.isJsonNull()){act++;continue;}if(act<=4)r.acts.add(act);}if(r.floor>0&&r.acts.isEmpty())r.acts.add(1);
  if(r.outcome.equals("death")&&!killed.isEmpty())r.add("death_count:"+killed,1,1);
  if(arrayField(o,"damage_taken")){r.available.add("encounter");r.available.add("damage");for(JsonElement e:arr(o,"damage_taken"))if(e.isJsonObject()){JsonObject b=e.getAsJsonObject();String enemy=str(b,"enemies");if(enemy.isEmpty())continue;Double damage=number(b,"damage");if(damage!=null)r.add("damage:"+enemy,damage,1);boolean dead=r.outcome.equals("death")&&num(b,"floor",-1)==r.floor&&enemy.equals(killed);r.add("death:"+enemy,dead?1:0,1);}}
  if(arrayField(o,"potions_floor_usage")){r.available.add("potions");r.add("potions",arr(o,"potions_floor_usage").size(),1);} // Explicit use records, never inferred from slot changes.
  if(arrayField(o,"potion_use_per_floor")){r.available.add("potions_by_encounter");Map<Integer,String> encounters=new HashMap<>();for(JsonElement e:arr(o,"damage_taken"))if(e.isJsonObject())encounters.put(num(e.getAsJsonObject(),"floor",-1),str(e.getAsJsonObject(),"enemies"));JsonArray uses=arr(o,"potion_use_per_floor");for(int i=0;i<uses.size();i++)if(uses.get(i).isJsonArray()&&encounters.containsKey(i+1))r.add("encounter_potions:"+encounters.get(i+1),uses.get(i).getAsJsonArray().size(),1);}
  if(arrayField(o,"items_purchased")){r.available.add("purchases");r.add("purchases",arr(o,"items_purchased").size(),1);for(JsonElement e:arr(o,"items_purchased"))if(e.isJsonPrimitive())r.add("purchase:"+cardId(e.getAsString()),1,1);}
  if(arrayField(o,"items_purged")){r.available.add("purges");for(JsonElement e:arr(o,"items_purged"))if(e.isJsonPrimitive())r.add("remove:shop:"+cardId(e.getAsString()),1,1);r.add("purges",arr(o,"items_purged").size(),1);}
  if(arrayField(o,"campfire_choices")){r.available.add("campfire");for(JsonElement e:arr(o,"campfire_choices"))if(e.isJsonObject()){JsonObject c=e.getAsJsonObject();String key=str(c,"key"),id=cardId(str(c,"data"));r.add("campfire:"+key,1,1);if(key.equals("SMITH")&&!id.isEmpty())r.add("upgrade:campfire:"+id,1,1);if(key.equals("PURGE")&&!id.isEmpty())r.add("remove:campfire:"+id,1,1);}}
  if(arrayField(o,"event_choices")){r.available.add("events");for(JsonElement e:arr(o,"event_choices"))if(e.isJsonObject()){JsonObject c=e.getAsJsonObject();String label=str(c,"event_name")+" / "+str(c,"player_choice");r.add("event:"+label,1,1);for(JsonElement card:arr(c,"cards_removed"))if(card.isJsonPrimitive())r.add("remove:event:"+cardId(card.getAsString()),1,1);for(JsonElement card:arr(c,"cards_upgraded"))if(card.isJsonPrimitive())r.add("upgrade:event:"+cardId(card.getAsString()),1,1);}}
  if(!str(o,"neow_bonus").isEmpty()){r.available.add("neow");r.add("neow:"+str(o,"neow_bonus")+" / "+str(o,"neow_cost"),1,1);}
  if(arrayField(o,"boss_relics")){r.available.add("boss_relics");int bossAct=0;for(JsonElement e:arr(o,"boss_relics")){bossAct++;if(!e.isJsonObject())continue;JsonObject c=e.getAsJsonObject();String picked=str(c,"picked");Set<String> all=new HashSet<>();all.add(picked);for(JsonElement other:arr(c,"not_picked"))if(other.isJsonPrimitive())all.add(other.getAsString());for(String id:all)if(!id.isEmpty())r.add("boss:"+bossAct+":"+id,id.equals(picked)?1:0,1);}}
  return r;
 }
 /** Follow only a confirmed checkpoint ancestry. Unknown parents are not stitched together. */
 static List<JsonObject> finalPath(JsonArray records,Run r){List<JsonObject> all=new ArrayList<>();Map<String,JsonObject> points=new HashMap<>(),loads=new HashMap<>();for(JsonElement e:records)if(e.isJsonObject()){JsonObject o=e.getAsJsonObject();all.add(o);String b=str(o,"branch_id"),type=str(o,"type");if(!b.isEmpty())r.lastBranch=b;if(type.equals("checkpoint"))points.put("save:"+str(o,"checkpoint_id"),o);if(type.equals("turn_snapshot"))points.put("turn:"+str(o,"snapshot_id"),o);if(type.equals("load")||type.equals("turn_rollback"))loads.put(b,o);}
  Map<String,Integer> ceilings=new HashMap<>();String branch=r.lastBranch;int ceiling=Integer.MAX_VALUE;Set<String> seen=new HashSet<>();while(!branch.isEmpty()&&seen.add(branch)){ceilings.put(branch,ceiling);JsonObject load=loads.get(branch);if(load==null)break;boolean turn=str(load,"type").equals("turn_rollback");JsonObject point=points.get(turn?"turn:"+str(load,"snapshot_id"):"save:"+str(load,"parent_checkpoint_id"));boolean known=turn?point!=null&&str(load,"parent_branch_id").equals(str(point,"branch_id")):"local_checkpoint_found".equals(str(load,"parent_status"));if(!known||point==null||num(point,"seq",-1)<0||num(point,"seq",-1)>=num(load,"seq",0)){r.pathExcluded++;break;}branch=str(point,"branch_id");ceiling=num(point,"seq",-1);}
  List<JsonObject> out=new ArrayList<>();for(JsonObject e:all){String b=str(e,"branch_id");if(ceilings.containsKey(b)&&num(e,"seq",0)<=ceilings.get(b))out.add(e);else if(r.lastBranch.isEmpty()&&b.isEmpty())out.add(e);}return out;
 }
 static Run notesRun(JsonObject document,HistoryIndex.Summary summary){Run r=new Run();r.source="notes";r.id=summary.id;r.playId=summary.playId;r.seed=summary.seed;r.character=summary.character;r.ascension=summary.ascension;r.time=summary.time;r.current=summary.current;r.fixture=summary.fixture;r.session=summary.sessionKind;r.conflict=summary.conflict;r.floor=0;if(summary.branches.size()>1)r.available.add("sl");
  Map<String,JsonObject> decisions=new LinkedHashMap<>(),results=new HashMap<>();Map<String,String> signatures=new HashMap<>();Set<String> conflicts=new HashSet<>();Set<String> changes=new HashSet<>();
  for(JsonObject e:finalPath(arr(document,"records"),r)){String type=str(e,"type");JsonObject before=obj(e,"before"),state=obj(e,"state"),after=obj(e,"after");for(JsonObject s:Arrays.asList(before,state,after)){if(s.has("act"))r.acts.add(num(s,"act",0));r.floor=Math.max(r.floor,num(s,"floor",0));}
   if(type.equals("ending")){String outcome=str(e,"outcome");r.outcome=Arrays.asList("victory","death","abandon").contains(outcome)?outcome:"incomplete";if(state.has("deck"))deck(r,arr(state,"deck"),true);if(outcome.equals("death"))r.heart=false;}
   if(type.equals("game_play_id")){r.playId=str(e,"play_id");r.heart=bool(e,"heart_kill");}
   if(type.equals("decision")||type.equals("result")){String id=str(e,"decision_id"),key=type+":"+id,sig=HistoryIndex.signature(e),old=signatures.putIfAbsent(key,sig);if(old!=null&&!old.equals(sig))conflicts.add(id);if(old==null)(type.equals("decision")?decisions:results).put(id,e);}
   if(type.equals("build_change")&&"settled".equals(str(e,"status"))&&changes.add(HistoryIndex.signature(e))){HistoryLayout.Delta d=HistoryLayout.delta(before,after);if(d.identitiesComplete)for(HistoryLayout.Change c:d.cards){if(c.kind.equals("removed"))r.add("remove:observed:"+str(c.before,"id"),1,1);if(c.kind.equals("changed")&&num(c.after,"upgrades",0)>num(c.before,"upgrades",0))r.add("upgrade:observed:"+str(c.after,"id"),1,1);}}
  }
  for(Map.Entry<String,JsonObject> item:decisions.entrySet()){String id=item.getKey();JsonObject d=item.getValue(),res=results.get(id);if(conflicts.contains(id)||res==null||!"confirmed".equals(str(res,"status"))||!"COMBAT_REWARD".equals(str(d,"source")))continue;JsonObject chosen=null;Set<String> appeared=new HashSet<>();boolean legal=true;for(JsonElement candidate:arr(d,"candidates"))if(candidate.isJsonObject()){JsonObject c=candidate.getAsJsonObject();if(str(c,"candidate_id").equals(str(d,"candidate_id"))){if(chosen!=null)legal=false;chosen=c;}if("card".equals(str(c,"type")))appeared.add(str(obj(c,"card"),"id"));}if(chosen==null||!legal)continue;int act=num(obj(d,"before"),"act",0);String kind=str(chosen,"type"),picked=str(obj(chosen,"card"),"id");if(!Arrays.asList("card","skip","bowl").contains(kind))continue;
   String actor=str(d,"action_source");r.available.add("actor:"+actor);r.available.add("reward");r.add("reward:"+act,1,1);r.add("skip:"+act,kind.equals("skip")?1:0,1);r.add("bowl:"+act,kind.equals("bowl")?1:0,1);for(String c:appeared)if(!c.isEmpty())r.add("pick:"+act+":"+c,kind.equals("card")&&picked.equals(c)?1:0,1);
  }Set<String> actors=new HashSet<>();for(String a:r.available)if(a.startsWith("actor:"))actors.add(a.substring(6));if(actors.size()==1)r.actor=actors.iterator().next();else if(actors.size()>1)r.actor="mixed";return r;
 }
 static JsonObject read(Path file)throws IOException{if(Files.isSymbolicLink(file)||Files.size(file)>HistoryIndex.MAX_BYTES)throw new IOException("file bounds");try(Reader reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){return new JsonParser().parse(reader).getAsJsonObject();}}
 static Index scan(Path nativeRoot,HistoryIndex.Index notes,JsonObject live)throws IOException{Index index=new Index();Map<String,Run> nativeById=new LinkedHashMap<>();Map<String,String> signatures=new HashMap<>();
  if(Files.isDirectory(nativeRoot)&&!Files.isSymbolicLink(nativeRoot))try(DirectoryStream<Path> dirs=Files.newDirectoryStream(nativeRoot)){for(Path dir:dirs)if(Files.isDirectory(dir)&&!Files.isSymbolicLink(dir))try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"*.run")){for(Path file:files)try{JsonObject data=read(file);if(str(data,"character_chosen").isEmpty())throw new IOException("Unrecognized native history format");Run r=nativeRun(data,dir.getFileName()+"/"+file.getFileName());String sig=HistoryIndex.signature(data),old=signatures.putIfAbsent(r.id,sig);if(old!=null){index.nativeDuplicates++;if(!old.equals(sig)){nativeById.get(r.id).conflict=true;index.conflicts++;}continue;}nativeById.put(r.id,r);}catch(Exception e){index.errors.add(file.getFileName()+": "+e.getClass().getSimpleName());}}}
  index.nativeRuns.addAll(nativeById.values());for(HistoryIndex.Summary summary:notes.runs)try{JsonObject data=summary.current&&live!=null?live:HistoryIndex.document(summary.file);Run r=notesRun(data,summary);Run n=nativeById.get(r.playId);if(n!=null&&!n.conflict&&!r.conflict){r.outcome=n.outcome;r.heart=n.heart;r.playtime=n.playtime; // Exact ID association, never seed.
    // Keep native result fields; candidate facts remain Spire Ledger only.
    n.values.putAll(r.values);n.available.addAll(r.available);n.actor=r.actor;n.fixture|=r.fixture;if(r.session.equals("practice"))n.session="practice";
   }else index.unlinked++;index.notesRuns.add(r);}catch(Exception e){index.errors.add(summary.id+": "+e.getClass().getSimpleName());}return index;
 }
 static List<Run> filter(Index index,Filter f,long now){List<Run> out=new ArrayList<>();for(Run r:f.scope.equals("notes")?index.notesRuns:index.nativeRuns)if((f.source.equals("all")||f.source.equals(r.actor))&&!r.fixture&&!r.session.equals("practice")&&!r.conflict&&!r.current&&(f.includeAbandon||!r.outcome.equals("abandon"))&&(f.character.isEmpty()||r.character.equals(f.character))&&(f.ascension<0||r.ascension==f.ascension)&&(f.days==0||r.time>0&&r.time>=now-f.days*86400000L)&&(f.from==0||r.time>=f.from)&&(f.to==0||r.time<f.to)&&(!f.slOnly||r.available.contains("sl")))out.add(r);return out;}
 static Boolean win(Run r,boolean heart){if(r.outcome.equals("death")||r.outcome.equals("abandon"))return false;if(!r.outcome.equals("victory"))return null;if(heart)return r.heart;return Boolean.TRUE;}
 static Map<String,Metric> metrics(List<Run> runs,Filter f){Map<String,Metric> out=new LinkedHashMap<>();Metric count=new Metric("runs","count");count.add(runs.size(),1);out.put(count.key,count);for(String key:Arrays.asList("victory","death","abandon","incomplete")){Metric m=new Metric("outcome:"+key,"count");for(Run r:runs)m.add(r.outcome.equals(key)?1:0,0);m.value=m.numerator;out.put(m.key,m);}
  Metric victories=new Metric("win","rate"),time=new Metric("time","seconds"),deck=new Metric("deck_size","cards");for(Run r:runs){Boolean w=win(r,f.heart);if(w==null)victories.excluded_count++;else victories.add(w?1:0,1);if(r.playtime==null)time.excluded_count++;else time.add(r.playtime,1);if(r.deckSize<0)deck.excluded_count++;else deck.add(r.deckSize,1);
   for(Map.Entry<String,double[]> entry:r.values.entrySet()){String key=entry.getKey();String unit=key.startsWith("pick:")||key.startsWith("skip:")||key.startsWith("bowl:")||key.startsWith("death:")||key.startsWith("boss:")?"rate":key.startsWith("damage:")?"hp":key.startsWith("encounter_potions:")?"potions":"count";Metric m=out.computeIfAbsent(key,k->new Metric(k,unit));m.add(entry.getValue()[0],entry.getValue()[1]);if(unit.equals("count"))m.value=m.numerator;}
   for(Map.Entry<String,double[]> selection:r.values.entrySet()){String k=selection.getKey();if((k.startsWith("neow:")||k.startsWith("boss:")||k.startsWith("event:"))&&selection.getValue()[0]>0){Metric related=out.computeIfAbsent("related:"+k,x->new Metric(x,"rate"));if(w==null)related.excluded_count++;else related.add(w?1:0,1);}}Boolean known=win(r,false);if(known!=null)for(String id:r.deck){Metric m=out.computeIfAbsent("holding:"+id,k->new Metric(k,"rate"));if(w==null)m.excluded_count++;else m.add(w?1:0,1);}
   int lastAct=r.acts.stream().mapToInt(Integer::intValue).max().orElse(0);for(int act:r.acts)if(act>0&&act<=4){Metric m=out.computeIfAbsent("act:"+act,k->new Metric(k,"rate"));if(act<lastAct)m.add(1,1);else if(known!=null)m.add(known?1:0,1);else m.excluded_count++;}
   if(r.pathExcluded>0){Metric m=out.computeIfAbsent("unresolved_path",k->new Metric(k,"count"));m.add(1,1);m.value=m.numerator;}
  }out.put("win",victories);out.put("time",time);out.put("deck_size",deck);
  for(String key:Arrays.asList("reward","damage","potions","purchases","purges","campfire","events","neow","boss_relics")){Metric m=new Metric("coverage:"+key,"rate");for(Run r:runs)m.add(r.available.contains(key)?1:0,1);out.put(m.key,m);}
  for(Metric m:out.values())if(m.denominator==0&&!m.unit.equals("count")||!m.unit.equals("count")&&m.eligible_count<f.minSamples)m.unavailable_reason=runs.isEmpty()?"暂无数据":"该项未记录或样本不足";return out;
 }
}
